import json, os, csv, sqlite3
uploads_dir = os.path.join(WORKSPACE_ROOT, 'uploads')
db_path = os.path.join(WORKSPACE_ROOT, 'data', 'agent.db')
os.makedirs(os.path.dirname(db_path), exist_ok=True)
fp = file_path if os.path.isabs(file_path) else os.path.join(uploads_dir, file_path)
if not os.path.exists(fp):
    result = {'success': False, 'error': f'File not found: {fp}'}
else:
    ext = os.path.splitext(fp)[1].lower()
    rows = []
    headers = []
    try:
        if ext in ('.xlsx', '.xlsm', '.xls'):
            import openpyxl
            wb = openpyxl.load_workbook(fp, read_only=True, data_only=True)
            sn = sheet_name if sheet_name else wb.sheetnames[0]
            ws = wb[sn]
            for i, row in enumerate(ws.iter_rows(values_only=True)):
                if i == 0:
                    headers = [str(c).strip() if c else f'col_{j}' for j, c in enumerate(row)]
                else:
                    vals = [str(c) if c is not None else '' for c in row]
                    if any(v for v in vals):
                        rows.append(vals)
            wb.close()
        elif ext == '.csv':
            with open(fp, 'r', encoding='utf-8-sig') as f:
                reader = csv.reader(f)
                headers = [h.strip() for h in next(reader)]
                for row in reader:
                    if any(v for v in row):
                        rows.append(row)
        else:
            result = {'success': False, 'error': f'Unsupported: {ext}'}
            rows = None
        if rows is not None:
            conn = sqlite3.connect(db_path)
            conn.execute('PRAGMA journal_mode=WAL')
            cursor = conn.cursor()
            if if_exists == 'replace':
                cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')
            elif if_exists == 'fail':
                cursor.execute(f"SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
                if cursor.fetchone():
                    conn.close()
                    result = {'success': False, 'error': f'Table {table_name} already exists'}
                    rows = None
            if rows is not None:
                col_defs = ', '.join([f'"{h}" TEXT' for h in headers])
                cursor.execute(f'CREATE TABLE IF NOT EXISTS "{table_name}" (id INTEGER PRIMARY KEY AUTOINCREMENT, {col_defs}, created_at TEXT DEFAULT (datetime("now")))')
                placeholders = ', '.join(['?' for _ in headers])
                col_names = ', '.join([f'"{h}"' for h in headers])
                insert_sql = f'INSERT INTO "{table_name}" ({col_names}) VALUES ({placeholders})'
                inserted = 0
                errors = []
                for idx, row in enumerate(rows):
                    try:
                        padded = row + [''] * (len(headers) - len(row))
                        cursor.execute(insert_sql, padded[:len(headers)])
                        inserted += 1
                    except Exception as e:
                        if len(errors) < 5:
                            errors.append(f'Row {idx+2}: {e}')
                conn.commit()
                conn.close()
                result = {'success': True, 'table': table_name, 'inserted': inserted, 'columns': headers, 'errors': errors}
    except Exception as e:
        result = {'success': False, 'error': str(e)}
